import type { ContentPack } from '../types';
import { glesson as G, lesson, M, mix, Nq, TF } from '../lib';
import { acceleration, atomParts, concentration, density, freeFall, massConservation, motionGraph, newton, siUnits, speed } from '../gensSci';
import { absRelError } from '../gensEso';

const P: ContentPack = {
  '2E-FQ-1': G(['Una magnitud es lo que se puede medir: longitud, masa, tiempo, temperatura… El Sistema Internacional (SI) fija sus unidades: metro (m), kilogramo (kg), segundo (s), kelvin (K).|Una magnitud és el que es pot mesurar: longitud, massa, temps, temperatura… El Sistema Internacional (SI) fixa les seues unitats: metre (m), quilogram (kg), segon (s), kelvin (K).|A quantity is something that can be measured: length, mass, time, temperature… The International System (SI) sets their units: metre (m), kilogram (kg), second (s), kelvin (K).', 'Para cambiar de unidad se usan factores de conversión.|Per a canviar d’unitat s’usen factors de conversió.|Conversion factors are used to change units.'],
    'Expresa 36 km/h en m/s.|Expressa 36 km/h en m/s.|Express 36 km/h in m/s.', ['36 km/h = 36 000 m / 3 600 s.|36 km/h = 36 000 m / 3 600 s.|36 km/h = 36,000 m ÷ 3,600 s.', '= 10 m/s.|= 10 m/s.|= 10 m/s.'], siUnits(), [
      M('¿Cuál es la unidad de masa en el SI?|Quina és la unitat de massa en el SI?|What is the SI unit of mass?', 'el kilogramo|el quilogram|the kilogram', ['el gramo|el gram|the gram', 'el newton|el newton|the newton'], 'Es la única unidad base con prefijo.|És l’única unitat base amb prefix.|It is the only base unit with a prefix.'),
      M('¿Cuál es la unidad de temperatura en el SI?|Quina és la unitat de temperatura en el SI?|What is the SI unit of temperature?', 'el kelvin|el kelvin|the kelvin', ['el grado Celsius|el grau Celsius|the degree Celsius', 'el julio|el joule|the joule'], 'K = °C + 273.|K = °C + 273.|K = °C + 273.'),
    ]),
  '2E-FQ-2': lesson(['El volumen de un líquido se mide con probeta, pipeta o bureta. Se lee en la parte baja del menisco, con los ojos a su altura.|El volum d’un líquid es mesura amb proveta, pipeta o bureta. Es llig en la part baixa del menisc, amb els ulls a la seua altura.|The volume of a liquid is measured with a measuring cylinder, pipette or burette. Read it at the bottom of the meniscus, with your eyes level with it.', 'El volumen de un sólido irregular se mide por desplazamiento de agua: lo que sube el nivel es su volumen.|El volum d’un sòlid irregular es mesura per desplaçament d’aigua: el que puja el nivell és el seu volum.|The volume of an irregular solid is measured by water displacement: the rise in level is its volume.'],
    'Una probeta marca 50 mL. Meto una piedra y marca 68 mL. ¿Volumen de la piedra?|Una proveta marca 50 mL. Hi pose una pedra i marca 68 mL. Volum de la pedra?|A measuring cylinder reads 50 mL. I add a stone and it reads 68 mL. Volume of the stone?', ['Lo que sube el agua es el volumen de la piedra.|El que puja l’aigua és el volum de la pedra.|The rise in water is the stone’s volume.', '68 − 50 = 18 mL = 18 cm³.|68 − 50 = 18 mL = 18 cm³.|68 − 50 = 18 mL = 18 cm³.'], [
      Nq('Una probeta marca 30 mL; al meter una llave, 34 mL. ¿Volumen de la llave (cm³)?|Una proveta marca 30 mL; en posar-hi una clau, 34 mL. Volum de la clau (cm³)?|A cylinder reads 30 mL; with a key in it, 34 mL. Volume of the key (cm³)?', 4, [34, 64, 30], 'Resta las dos lecturas. 1 mL = 1 cm³.|Resta les dues lectures. 1 mL = 1 cm³.|Subtract the two readings. 1 mL = 1 cm³.'),
      M('¿Dónde se lee el volumen en una probeta?|On es llig el volum en una proveta?|Where do you read the volume in a measuring cylinder?', 'en la parte baja del menisco|en la part baixa del menisc|at the bottom of the meniscus', ['en la parte alta del menisco|en la part alta del menisc|at the top of the meniscus', 'en el borde del vidrio|en la vora del vidre|at the edge of the glass'], 'Con los ojos a la altura del líquido.|Amb els ulls a l’altura del líquid.|With your eyes level with the liquid.'),
      M('Para medir 10 mL con mucha precisión, ¿qué usas?|Per a mesurar 10 mL amb molta precisió, què uses?|To measure 10 mL very precisely, what do you use?', 'una pipeta|una pipeta|a pipette', ['un vaso de precipitados|un got de precipitats|a beaker', 'un embudo|un embut|a funnel'], 'El vaso de precipitados solo da medidas aproximadas.|El got de precipitats només dona mesures aproximades.|A beaker only gives rough measurements.'),
      Nq('¿Cuántos mL son 1,5 L?|Quants mL són 1,5 L?|How many mL are 1.5 L?', 1500, [150, 15, 15000], '1 L = 1 000 mL.|1 L = 1 000 mL.|1 L = 1,000 mL.'),
      TF('1 mL equivale a 1 cm³.|1 mL equival a 1 cm³.|1 mL is the same as 1 cm³.', true, 'Por eso se usa agua para medir sólidos.|Per això s’usa aigua per a mesurar sòlids.|That is why water is used to measure solids.'),
      M('Si miras la probeta desde arriba, la lectura sale…|Si mires la proveta des de dalt, la lectura ix…|If you look at the cylinder from above, the reading is…', 'incorrecta (error de paralaje)|incorrecta (error de paral·laxi)|wrong (parallax error)', ['más exacta|més exacta|more accurate', 'igual|igual|the same'], 'Los ojos deben estar a la altura del líquido.|Els ulls han d’estar a l’altura del líquid.|Your eyes must be level with the liquid.'),
    ]),
  '2E-FQ-3': G(['Toda medida tiene error. Error absoluto: diferencia con el valor real. Error relativo: error absoluto ÷ valor real. Los datos se recogen en tablas y se representan en gráficas con ejes, unidades y escala.|Tota mesura té error. Error absolut: diferència amb el valor real. Error relatiu: error absolut ÷ valor real. Les dades es recullen en taules i es representen en gràfiques amb eixos, unitats i escala.|Every measurement has an error. Absolute error: difference from the true value. Relative error: absolute error ÷ true value. Data is recorded in tables and plotted on graphs with axes, units and a scale.'],
    'Mido 10,3 cm y lo real es 10,0 cm. ¿Error absoluto?|Mesure 10,3 cm i el real és 10,0 cm. Error absolut?|I measure 10.3 cm and the true value is 10.0 cm. Absolute error?', ['10,3 − 10,0.|10,3 − 10,0.|10.3 − 10.0.', '0,3 cm.|0,3 cm.|0.3 cm.'], mix(absRelError(), motionGraph())),
  '2E-FQ-4': lesson(['La ciencia la han construido muchas personas, también mujeres a menudo olvidadas: Marie Curie (radiactividad), Lise Meitner (fisión nuclear), Rosalind Franklin (estructura del ADN), Margarita Salas (bioquímica).|La ciència l’han construïda moltes persones, també dones sovint oblidades: Marie Curie (radioactivitat), Lise Meitner (fissió nuclear), Rosalind Franklin (estructura de l’ADN), Margarita Salas (bioquímica).|Science has been built by many people, including often forgotten women: Marie Curie (radioactivity), Lise Meitner (nuclear fission), Rosalind Franklin (DNA structure), Margarita Salas (biochemistry).'],
    '¿Quién ganó dos premios Nobel en ciencias distintas?|Qui va guanyar dos premis Nobel en ciències diferents?|Who won two Nobel Prizes in different sciences?', ['Física (1903) y Química (1911).|Física (1903) i Química (1911).|Physics (1903) and Chemistry (1911).', 'Marie Curie.|Marie Curie.|Marie Curie.'], [
      M('¿Qué estudió Marie Curie?|Què va estudiar Marie Curie?|What did Marie Curie study?', 'la radiactividad|la radioactivitat|radioactivity', ['la gravedad|la gravetat|gravity', 'la evolución|l’evolució|evolution'], 'Descubrió el polonio y el radio.|Va descobrir el poloni i el radi.|She discovered polonium and radium.'),
      M('¿Qué ley explicó la caída de los cuerpos y el movimiento de los planetas?|Quina llei va explicar la caiguda dels cossos i el moviment dels planetes?|Which law explained falling objects and planetary motion?', 'la gravitación universal de Newton|la gravitació universal de Newton|Newton’s law of universal gravitation', ['la ley de Ohm|la llei d’Ohm|Ohm’s law', 'la ley de Hooke|la llei de Hooke|Hooke’s law'], 'Isaac Newton, siglo XVII.|Isaac Newton, segle XVII.|Isaac Newton, 17th century.'),
      M('¿Quién organizó los elementos en la tabla periódica?|Qui va organitzar els elements en la taula periòdica?|Who arranged the elements in the periodic table?', 'Dmitri Mendeléiev|Dmitri Mendeléiev|Dmitri Mendeleev', ['Albert Einstein|Albert Einstein|Albert Einstein', 'Charles Darwin|Charles Darwin|Charles Darwin'], 'En 1869, dejando huecos para elementos aún no descubiertos.|En 1869, deixant buits per a elements encara no descoberts.|In 1869, leaving gaps for undiscovered elements.'),
      M('Lise Meitner explicó…|Lise Meitner va explicar…|Lise Meitner explained…', 'la fisión nuclear|la fissió nuclear|nuclear fission', ['la fotosíntesis|la fotosíntesi|photosynthesis', 'la electricidad estática|l’electricitat estàtica|static electricity'], 'El núcleo se parte y libera energía.|El nucli es parteix i allibera energia.|A nucleus splits and releases energy.'),
      M('Margarita Salas fue una científica española que investigó en…|Margarita Salas va ser una científica espanyola que va investigar en…|Margarita Salas was a Spanish scientist who worked on…', 'bioquímica y biología molecular|bioquímica i biologia molecular|biochemistry and molecular biology', ['astronomía|astronomia|astronomy', 'geología|geologia|geology'], 'Patentó un método para copiar ADN.|Va patentar un mètode per a copiar ADN.|She patented a method for copying DNA.'),
      TF('La ciencia avanza con el trabajo de muchas personas, no solo de genios aislados.|La ciència avança amb el treball de moltes persones, no sols de genis aïllats.|Science advances through the work of many people, not just lone geniuses.', true, 'Se comparte, se revisa y se mejora.|Es compartix, es revisa i es millora.|It is shared, checked and improved.'),
    ]),
  '2E-FQ-5': lesson(['Método científico: observar, hacer una pregunta, formular una hipótesis, diseñar un experimento (cambiando solo una variable), recoger datos, analizarlos y sacar conclusiones.|Mètode científic: observar, fer una pregunta, formular una hipòtesi, dissenyar un experiment (canviant només una variable), recollir dades, analitzar-les i traure conclusions.|Scientific method: observe, ask a question, form a hypothesis, design an experiment (changing only one variable), collect data, analyse it and draw conclusions.', 'Variable independiente: la que cambias. Dependiente: la que mides. Controladas: las que mantienes iguales.|Variable independent: la que canvies. Dependent: la que mesures. Controlades: les que mantens iguals.|Independent variable: the one you change. Dependent: the one you measure. Control variables: the ones you keep the same.'],
    '¿Influye la temperatura del agua en lo que tarda en disolverse el azúcar?|Influïx la temperatura de l’aigua en el que tarda a dissoldre’s el sucre?|Does water temperature affect how long sugar takes to dissolve?', ['Independiente: temperatura. Dependiente: tiempo.|Independent: temperatura. Dependent: temps.|Independent: temperature. Dependent: time.', 'Controladas: cantidad de agua y de azúcar, remover igual.|Controlades: quantitat d’aigua i de sucre, remenar igual.|Control: amount of water and sugar, stirring the same.'], [
      M('Una hipótesis es…|Una hipòtesi és…|A hypothesis is…', 'una posible explicación que se puede comprobar|una possible explicació que es pot comprovar|a possible explanation that can be tested', ['una conclusión segura|una conclusió segura|a certain conclusion', 'una opinión personal|una opinió personal|a personal opinion'], 'Se pone a prueba con experimentos.|Es posa a prova amb experiments.|It is tested by experiments.'),
      M('Estudio si la luz afecta al crecimiento de plantas. ¿Variable independiente?|Estudie si la llum afecta el creixement de plantes. Variable independent?|I study whether light affects plant growth. Independent variable?', 'la cantidad de luz|la quantitat de llum|the amount of light', ['la altura de la planta|l’altura de la planta|the height of the plant', 'el tipo de maceta|el tipus de test|the type of pot'], 'Es la que tú cambias.|És la que tu canvies.|It is the one you change.'),
      M('En el mismo experimento, ¿variable dependiente?|En el mateix experiment, variable dependent?|In the same experiment, the dependent variable?', 'la altura de la planta|l’altura de la planta|the height of the plant', ['la cantidad de luz|la quantitat de llum|the amount of light', 'el agua de riego|l’aigua de reg|the watering'], 'Es la que mides.|És la que mesures.|It is the one you measure.'),
      TF('En un buen experimento se cambia una sola variable a la vez.|En un bon experiment es canvia una sola variable alhora.|In a good experiment only one variable is changed at a time.', true, 'Así sabes qué causa el efecto.|Així saps què causa l’efecte.|That way you know what causes the effect.'),
      M('¿Qué paso va después de recoger los datos?|Quin pas va després de recollir les dades?|Which step comes after collecting data?', 'analizarlos|analitzar-les|analysing them', ['formular la hipótesis|formular la hipòtesi|forming the hypothesis', 'observar|observar|observing'], 'Tablas y gráficas ayudan.|Taules i gràfiques ajuden.|Tables and graphs help.'),
      TF('Si los datos no confirman la hipótesis, el experimento no sirve para nada.|Si les dades no confirmen la hipòtesi, l’experiment no servix per a res.|If the data does not support the hypothesis, the experiment is useless.', false, 'Descartar una hipótesis también es aprender.|Descartar una hipòtesi també és aprendre.|Rejecting a hypothesis is also learning.'),
    ]),
  '2E-FQ-6': G(['La densidad es la masa que hay en cada unidad de volumen: d = m / V. Se mide en g/cm³ o kg/m³. Lo menos denso flota sobre lo más denso.|La densitat és la massa que hi ha en cada unitat de volum: d = m / V. Es mesura en g/cm³ o kg/m³. El menys dens sura sobre el més dens.|Density is the mass in each unit of volume: d = m ÷ V. It is measured in g/cm³ or kg/m³. Less dense things float on denser ones.'],
    'Un cubo de 10 cm³ tiene 27 g. ¿Densidad?|Un cub de 10 cm³ té 27 g. Densitat?|A 10 cm³ cube has a mass of 27 g. Density?', ['d = 27 / 10.|d = 27 / 10.|d = 27 ÷ 10.', '2,7 g/cm³ (aluminio).|2,7 g/cm³ (alumini).|2.7 g/cm³ (aluminium).'], density()),
  '2E-FQ-7': lesson(['La materia se presenta en tres estados: sólido (forma y volumen fijos), líquido (volumen fijo, forma del recipiente) y gas (ni forma ni volumen fijos). El modelo de partículas lo explica por cómo de juntas y libres están.|La matèria es presenta en tres estats: sòlid (forma i volum fixos), líquid (volum fix, forma del recipient) i gas (ni forma ni volum fixos). El model de partícules ho explica per com de juntes i lliures estan.|Matter comes in three states: solid (fixed shape and volume), liquid (fixed volume, takes the container’s shape) and gas (no fixed shape or volume). The particle model explains this by how close and free the particles are.'],
    '¿Por qué un gas se puede comprimir y un sólido no?|Per què un gas es pot comprimir i un sòlid no?|Why can a gas be compressed but a solid cannot?', ['En el gas las partículas están muy separadas.|En el gas les partícules estan molt separades.|In a gas the particles are far apart.', 'En el sólido están juntas y fijas.|En el sòlid estan juntes i fixes.|In a solid they are close and fixed.'], [
      M('¿Qué estado tiene volumen fijo pero adopta la forma del recipiente?|Quin estat té volum fix però adopta la forma del recipient?|Which state has a fixed volume but takes the shape of its container?', 'líquido|líquid|liquid', ['sólido|sòlid|solid', 'gas|gas|gas'], 'Piensa en el agua en un vaso.|Pensa en l’aigua en un got.|Think of water in a glass.'),
      M('¿En qué estado las partículas solo vibran en posiciones fijas?|En quin estat les partícules només vibren en posicions fixes?|In which state do particles only vibrate in fixed positions?', 'sólido|sòlid|solid', ['líquido|líquid|liquid', 'gas|gas|gas'], 'Por eso tiene forma propia.|Per això té forma pròpia.|That is why it keeps its shape.'),
      M('¿Qué estado llena todo el recipiente?|Quin estat ompli tot el recipient?|Which state fills the whole container?', 'gas|gas|gas', ['líquido|líquid|liquid', 'sólido|sòlid|solid'], 'Sus partículas se mueven libres en todas direcciones.|Les seues partícules es mouen lliures en totes direccions.|Its particles move freely in all directions.'),
      TF('Al calentar una sustancia, sus partículas se mueven más deprisa.|En escalfar una substància, les seues partícules es mouen més de pressa.|When a substance is heated, its particles move faster.', true, 'La temperatura mide esa agitación.|La temperatura mesura eixa agitació.|Temperature measures that movement.'),
      M('El olor de un perfume se extiende por la habitación porque…|L’olor d’un perfum s’estén per l’habitació perquè…|A perfume’s smell spreads through a room because…', 'las partículas del gas se mueven y se mezclan con el aire|les partícules del gas es mouen i es mesclen amb l’aire|gas particles move and mix with the air', ['el perfume se hace sólido|el perfum es fa sòlid|the perfume becomes solid', 'el aire empuja el olor|l’aire empeny l’olor|the air pushes the smell'], 'Se llama difusión.|Es diu difusió.|It is called diffusion.'),
      TF('Entre las partículas de un gas hay vacío.|Entre les partícules d’un gas hi ha buit.|There is empty space between gas particles.', true, 'Nada, ni siquiera aire.|Res, ni tan sols aire.|Nothing, not even air.'),
    ]),
  '2E-FQ-8': lesson(['Cambios de estado: fusión (sólido → líquido), solidificación (líquido → sólido), vaporización (líquido → gas; por ebullición o evaporación), condensación (gas → líquido), sublimación (sólido → gas) y sublimación inversa.|Canvis d’estat: fusió (sòlid → líquid), solidificació (líquid → sòlid), vaporització (líquid → gas; per ebullició o evaporació), condensació (gas → líquid), sublimació (sòlid → gas) i sublimació inversa.|Changes of state: melting (solid → liquid), freezing (liquid → solid), vaporisation (liquid → gas; boiling or evaporation), condensation (gas → liquid), sublimation (solid → gas) and deposition.', 'Mientras cambia de estado, la temperatura de una sustancia pura no varía.|Mentre canvia d’estat, la temperatura d’una substància pura no varia.|While a pure substance changes state, its temperature stays the same.'],
    'Se empaña el espejo del baño. ¿Qué cambio de estado es?|S’entela l’espill del bany. Quin canvi d’estat és?|The bathroom mirror steams up. Which change of state is it?', ['El vapor de agua se enfría al tocar el espejo.|El vapor d’aigua es refreda en tocar l’espill.|Water vapour cools when it touches the mirror.', 'Pasa de gas a líquido: condensación.|Passa de gas a líquid: condensació.|Gas to liquid: condensation.'], [
      M('Un cubito de hielo se derrite. Es…|Un glaçó es fon. És…|An ice cube melts. That is…', 'fusión|fusió|melting', ['solidificación|solidificació|freezing', 'sublimación|sublimació|sublimation'], 'Sólido → líquido.|Sòlid → líquid.|Solid → liquid.'),
      M('La ropa tendida se seca. Es…|La roba estesa s’eixuga. És…|Washing on the line dries. That is…', 'evaporación|evaporació|evaporation', ['ebullición|ebullició|boiling', 'condensación|condensació|condensation'], 'Ocurre en la superficie y a cualquier temperatura.|Passa en la superfície i a qualsevol temperatura.|It happens at the surface, at any temperature.'),
      M('El agua pura hierve a nivel del mar a…|L’aigua pura bull a nivell de la mar a…|Pure water boils at sea level at…', '100 °C|100 °C|100 °C', ['0 °C|0 °C|0 °C', '50 °C|50 °C|50 °C'], 'Es su punto de ebullición.|És el seu punt d’ebullició.|It is its boiling point.'),
      M('El hielo seco (CO₂ sólido) pasa directamente a gas. Es…|El gel sec (CO₂ sòlid) passa directament a gas. És…|Dry ice (solid CO₂) turns straight into gas. That is…', 'sublimación|sublimació|sublimation', ['fusión|fusió|melting', 'condensación|condensació|condensation'], 'Sólido → gas sin pasar por líquido.|Sòlid → gas sense passar per líquid.|Solid → gas without becoming liquid.'),
      TF('Mientras el agua hierve, su temperatura sigue subiendo.|Mentre l’aigua bull, la seua temperatura continua pujant.|While water is boiling, its temperature keeps rising.', false, 'Se queda a 100 °C hasta que toda se evapora.|Es queda a 100 °C fins que tota s’evapora.|It stays at 100 °C until it has all boiled away.'),
      M('El agua líquida se convierte en hielo en el congelador. Es…|L’aigua líquida es convertix en gel en el congelador. És…|Liquid water turns to ice in the freezer. That is…', 'solidificación|solidificació|freezing', ['fusión|fusió|melting', 'vaporización|vaporització|vaporisation'], 'Líquido → sólido.|Líquid → sòlid.|Liquid → solid.'),
    ]),
  '2E-FQ-9': lesson(['Una mezcla tiene varias sustancias. Es heterogénea si se distinguen sus componentes (agua con arena) y homogénea o disolución si no (agua con sal). En una disolución, el soluto se disuelve en el disolvente.|Una mescla té diverses substàncies. És heterogènia si es distingixen els seus components (aigua amb arena) i homogènia o dissolució si no (aigua amb sal). En una dissolució, el solut es dissol en el dissolvent.|A mixture contains several substances. It is heterogeneous if you can see the parts (water and sand) and homogeneous, a solution, if not (salt water). In a solution, the solute dissolves in the solvent.'],
    'En el agua con azúcar, ¿cuál es el soluto?|En l’aigua amb sucre, quin és el solut?|In sugar water, which is the solute?', ['El disolvente está en mayor cantidad: el agua.|El dissolvent està en major quantitat: l’aigua.|The solvent is the main part: the water.', 'El soluto es el azúcar.|El solut és el sucre.|The solute is the sugar.'], [
      M('¿Qué es una mezcla heterogénea?|Què és una mescla heterogènia?|Which is a heterogeneous mixture?', 'agua con aceite|aigua amb oli|water and oil', ['agua con sal|aigua amb sal|salt water', 'aire limpio|aire net|clean air'], 'Se ven las dos sustancias.|Es veuen les dues substàncies.|You can see both substances.'),
      M('¿Qué es una disolución?|Què és una dissolució?|Which is a solution?', 'el agua del mar|l’aigua de la mar|seawater', ['la arena de la playa|l’arena de la platja|beach sand', 'una ensalada|una ensalada|a salad'], 'No se distinguen sus componentes.|No es distingixen els seus components.|You cannot see the parts.'),
      M('En una disolución de sal en agua, el disolvente es…|En una dissolució de sal en aigua, el dissolvent és…|In salt water, the solvent is…', 'el agua|l’aigua|the water', ['la sal|la sal|the salt', 'el vaso|el got|the glass'], 'Es el componente mayoritario.|És el component majoritari.|It is the main component.'),
      TF('El aire es una disolución de gases.|L’aire és una dissolució de gasos.|Air is a solution of gases.', true, 'Nitrógeno, oxígeno y otros, mezclados uniformemente.|Nitrogen, oxigen i altres, mesclats uniformement.|Nitrogen, oxygen and others, evenly mixed.'),
      M('Una aleación como el bronce es…|Un aliatge com el bronze és…|An alloy such as bronze is…', 'una disolución sólida|una dissolució sòlida|a solid solution', ['una sustancia pura|una substància pura|a pure substance', 'una mezcla heterogénea|una mescla heterogènia|a heterogeneous mixture'], 'Cobre y estaño mezclados uniformemente.|Coure i estany mesclats uniformement.|Copper and tin evenly mixed.'),
      TF('En una disolución puede haber más de un soluto.|En una dissolució hi pot haver més d’un solut.|A solution can have more than one solute.', true, 'El agua del mar tiene muchas sales.|L’aigua de la mar té moltes sals.|Seawater contains many salts.'),
    ]),
  '2E-FQ-10': lesson(['Una sustancia pura tiene composición fija y propiedades características (densidad, punto de fusión y de ebullición). Puede ser un elemento (un solo tipo de átomo) o un compuesto (varios tipos unidos).|Una substància pura té composició fixa i propietats característiques (densitat, punt de fusió i d’ebullició). Pot ser un element (un sol tipus d’àtom) o un compost (diversos tipus units).|A pure substance has a fixed composition and characteristic properties (density, melting and boiling points). It can be an element (one kind of atom) or a compound (several kinds joined).'],
    '¿Cómo distinguir agua pura de agua con sal?|Com distingir aigua pura d’aigua amb sal?|How can you tell pure water from salt water?', ['El agua pura hierve a 100 °C y su temperatura se mantiene.|L’aigua pura bull a 100 °C i la seua temperatura es manté.|Pure water boils at 100 °C and the temperature stays constant.', 'El agua salada hierve a más temperatura y esta va subiendo.|L’aigua salada bull a més temperatura i esta va pujant.|Salt water boils hotter and the temperature keeps rising.'], [
      M('¿Cuál es una sustancia pura?|Quina és una substància pura?|Which is a pure substance?', 'agua destilada|aigua destil·lada|distilled water', ['agua del grifo|aigua de l’aixeta|tap water', 'zumo de naranja|suc de taronja|orange juice'], 'Solo contiene H₂O.|Només conté H₂O.|It only contains H₂O.'),
      M('¿Qué propiedad sirve para identificar una sustancia pura?|Quina propietat servix per a identificar una substància pura?|Which property identifies a pure substance?', 'su punto de ebullición|el seu punt d’ebullició|its boiling point', ['su masa|la seua massa|its mass', 'su volumen|el seu volum|its volume'], 'La masa y el volumen dependen de la cantidad.|La massa i el volum depenen de la quantitat.|Mass and volume depend on the amount.'),
      M('El oxígeno (O₂) es…|L’oxigen (O₂) és…|Oxygen (O₂) is…', 'un elemento|un element|an element', ['un compuesto|un compost|a compound', 'una mezcla|una mescla|a mixture'], 'Solo tiene átomos de oxígeno.|Només té àtoms d’oxigen.|It only has oxygen atoms.'),
      M('El agua (H₂O) es…|L’aigua (H₂O) és…|Water (H₂O) is…', 'un compuesto|un compost|a compound', ['un elemento|un element|an element', 'una mezcla|una mescla|a mixture'], 'Une hidrógeno y oxígeno.|Unix hidrogen i oxigen.|It joins hydrogen and oxygen.'),
      TF('La densidad es una propiedad característica.|La densitat és una propietat característica.|Density is a characteristic property.', true, 'No depende de cuánta sustancia tengas.|No depén de quanta substància tingues.|It does not depend on how much you have.'),
      TF('El aire es una sustancia pura.|L’aire és una substància pura.|Air is a pure substance.', false, 'Es una mezcla de gases.|És una mescla de gasos.|It is a mixture of gases.'),
    ]),
  '2E-FQ-11': lesson(['Técnicas de separación: filtración (sólido de líquido), decantación (líquidos que no se mezclan), evaporación y cristalización (sólido disuelto), destilación (líquidos con distinto punto de ebullición), imantación (metales magnéticos), tamizado (sólidos de distinto tamaño).|Tècniques de separació: filtració (sòlid de líquid), decantació (líquids que no es mesclen), evaporació i cristal·lització (sòlid dissolt), destil·lació (líquids amb diferent punt d’ebullició), imantació (metalls magnètics), tamisatge (sòlids de diferent grandària).|Separation techniques: filtering (solid from liquid), decanting (liquids that do not mix), evaporation and crystallisation (dissolved solid), distillation (liquids with different boiling points), magnetism (magnetic metals), sieving (solids of different sizes).'],
    '¿Cómo separas arena, sal y agua?|Com separes arena, sal i aigua?|How do you separate sand, salt and water?', ['Filtro: la arena queda en el papel.|Filtre: l’arena queda en el paper.|Filter: the sand stays in the paper.', 'Evaporo el agua: queda la sal.|Evapore l’aigua: queda la sal.|Evaporate the water: the salt is left.'], [
      M('Para separar agua y aceite se usa…|Per a separar aigua i oli s’usa…|To separate water and oil you use…', 'decantación|decantació|decanting', ['filtración|filtració|filtering', 'imantación|imantació|a magnet'], 'Un embudo de decantación deja salir primero el líquido de abajo.|Un embut de decantació deixa eixir primer el líquid de baix.|A separating funnel lets the bottom liquid out first.'),
      M('Para separar limaduras de hierro de arena se usa…|Per a separar llimadures de ferro d’arena s’usa…|To separate iron filings from sand you use…', 'un imán|un imant|a magnet', ['un filtro|un filtre|a filter', 'destilación|destil·lació|distillation'], 'El hierro es magnético.|El ferro és magnètic.|Iron is magnetic.'),
      M('Para separar alcohol y agua se usa…|Per a separar alcohol i aigua s’usa…|To separate alcohol and water you use…', 'destilación|destil·lació|distillation', ['decantación|decantació|decanting', 'tamizado|tamisatge|sieving'], 'Hierven a temperaturas distintas.|Bullen a temperatures diferents.|They boil at different temperatures.'),
      M('En las salinas de Santa Pola se obtiene sal por…|A les salines de Santa Pola s’obté sal per…|At the Santa Pola salt pans, salt is obtained by…', 'evaporación|evaporació|evaporation', ['filtración|filtració|filtering', 'imantación|imantació|a magnet'], 'El sol evapora el agua del mar.|El sol evapora l’aigua de la mar.|The sun evaporates the seawater.'),
      M('Para separar arena y agua se usa…|Per a separar arena i aigua s’usa…|To separate sand and water you use…', 'filtración|filtració|filtering', ['destilación|destil·lació|distillation', 'imantación|imantació|a magnet'], 'La arena no atraviesa el papel de filtro.|L’arena no travessa el paper de filtre.|Sand does not pass through filter paper.'),
      M('Para separar piedras de arena se usa…|Per a separar pedres d’arena s’usa…|To separate stones from sand you use…', 'un tamiz|un tamís|a sieve', ['un imán|un imant|a magnet', 'decantación|decantació|decanting'], 'Separa por tamaño.|Separa per grandària.|It separates by size.'),
    ]),
  '2E-FQ-12': G(['La concentración dice cuánto soluto hay en la disolución. En g/L: masa de soluto (g) / volumen de disolución (L). En % en masa: masa de soluto / masa de disolución · 100.|La concentració diu quant de solut hi ha en la dissolució. En g/L: massa de solut (g) / volum de dissolució (L). En % en massa: massa de solut / massa de dissolució · 100.|Concentration tells how much solute is in the solution. In g/L: mass of solute (g) ÷ volume of solution (L). As % by mass: mass of solute ÷ mass of solution × 100.'],
    '20 g de sal en 500 mL de disolución. ¿g/L?|20 g de sal en 500 mL de dissolució. g/L?|20 g of salt in 500 mL of solution. g/L?', ['500 mL = 0,5 L.|500 mL = 0,5 L.|500 mL = 0.5 L.', '20 / 0,5 = 40 g/L.|20 / 0,5 = 40 g/L.|20 ÷ 0.5 = 40 g/L.'], concentration()),
  '2E-FQ-13': lesson(['La solubilidad es la máxima cantidad de soluto que se disuelve en una cantidad de disolvente a una temperatura. Una disolución saturada ya no admite más soluto. En la mayoría de sólidos, aumenta con la temperatura; en los gases, disminuye.|La solubilitat és la màxima quantitat de solut que es dissol en una quantitat de dissolvent a una temperatura. Una dissolució saturada ja no admet més solut. En la majoria de sòlids, augmenta amb la temperatura; en els gasos, disminuïx.|Solubility is the maximum amount of solute that dissolves in a given amount of solvent at a given temperature. A saturated solution cannot take any more. For most solids it rises with temperature; for gases it falls.'],
    'La solubilidad de una sal es 36 g por 100 g de agua. Echo 50 g en 100 g de agua. ¿Qué pasa?|La solubilitat d’una sal és 36 g per 100 g d’aigua. En tire 50 g en 100 g d’aigua. Què passa?|A salt’s solubility is 36 g per 100 g of water. I add 50 g to 100 g of water. What happens?', ['Solo se disuelven 36 g.|Només es dissolen 36 g.|Only 36 g dissolve.', 'Quedan 14 g sin disolver en el fondo.|En queden 14 g sense dissoldre en el fons.|14 g stay undissolved at the bottom.'], [
      Nq('Solubilidad: 30 g por 100 g de agua. ¿Cuántos gramos se disuelven como máximo en 300 g de agua?|Solubilitat: 30 g per 100 g d’aigua. Quants grams es dissolen com a màxim en 300 g d’aigua?|Solubility: 30 g per 100 g of water. What is the most that dissolves in 300 g of water (g)?', 90, [30, 100, 330], 'El triple de agua, el triple de soluto.|El triple d’aigua, el triple de solut.|Three times the water, three times the solute.'),
      M('Una disolución que ya no admite más soluto es…|Una dissolució que ja no admet més solut és…|A solution that cannot take any more solute is…', 'saturada|saturada|saturated', ['diluida|diluïda|dilute', 'concentrada|concentrada|concentrated'], 'Si añades más, se queda en el fondo.|Si n’afegixes més, es queda en el fons.|Any more stays at the bottom.'),
      TF('El azúcar se disuelve mejor en agua caliente.|El sucre es dissol millor en aigua calenta.|Sugar dissolves better in hot water.', true, 'En la mayoría de sólidos, la solubilidad sube con la temperatura.|En la majoria de sòlids, la solubilitat puja amb la temperatura.|For most solids, solubility rises with temperature.'),
      TF('Un refresco caliente pierde el gas antes que uno frío.|Un refresc calent perd el gas abans que un de fred.|A warm fizzy drink goes flat faster than a cold one.', true, 'Los gases son menos solubles en caliente.|Els gasos són menys solubles en calent.|Gases are less soluble when warm.'),
      M('Los peces pueden tener problemas en aguas muy calientes porque…|Els peixos poden tindre problemes en aigües molt calentes perquè…|Fish can struggle in very warm water because…', 'hay menos oxígeno disuelto|hi ha menys oxigen dissolt|there is less dissolved oxygen', ['hay más sal|hi ha més sal|there is more salt', 'el agua pesa más|l’aigua pesa més|the water is heavier'], 'Los gases se disuelven peor en caliente.|Els gasos es dissolen pitjor en calent.|Gases dissolve less in warm water.'),
      M('Una disolución con poco soluto es…|Una dissolució amb poc solut és…|A solution with little solute is…', 'diluida|diluïda|dilute', ['saturada|saturada|saturated', 'sobresaturada|sobresaturada|supersaturated'], 'Diluido = poco concentrado.|Diluït = poc concentrat.|Dilute = weak.'),
    ]),
  '2E-FQ-14': lesson(['Las sustancias puras pueden ser simples (un solo elemento: O₂, Fe, N₂) o compuestas (varios elementos unidos en proporción fija: H₂O, CO₂, NaCl). Un compuesto se puede descomponer en sustancias más sencillas por métodos químicos.|Les substàncies pures poden ser simples (un sol element: O₂, Fe, N₂) o compostes (diversos elements units en proporció fixa: H₂O, CO₂, NaCl). Un compost es pot descompondre en substàncies més senzilles per mètodes químics.|Pure substances can be elements (one element: O₂, Fe, N₂) or compounds (several elements joined in a fixed ratio: H₂O, CO₂, NaCl). A compound can be broken down chemically into simpler substances.'],
    '¿El CO₂ es simple o compuesto?|El CO₂ és simple o compost?|Is CO₂ an element or a compound?', ['Tiene carbono y oxígeno.|Té carboni i oxigen.|It contains carbon and oxygen.', 'Dos elementos: compuesto.|Dos elements: compost.|Two elements: a compound.'], [
      M('¿Cuál es una sustancia simple?|Quina és una substància simple?|Which is an element?', 'N₂|N₂|N₂', ['H₂O|H₂O|H₂O', 'NaCl|NaCl|NaCl'], 'Solo tiene un tipo de átomo.|Només té un tipus d’àtom.|It has only one kind of atom.'),
      M('¿Cuál es un compuesto?|Quin és un compost?|Which is a compound?', 'NaCl (sal común)|NaCl (sal comuna)|NaCl (table salt)', ['Fe (hierro)|Fe (ferro)|Fe (iron)', 'O₂ (oxígeno)|O₂ (oxigen)|O₂ (oxygen)'], 'Une sodio y cloro.|Unix sodi i clor.|It joins sodium and chlorine.'),
      Nq('¿Cuántos elementos distintos hay en H₂SO₄?|Quants elements diferents hi ha en H₂SO₄?|How many different elements are in H₂SO₄?', 3, [7, 2, 4], 'H, S y O.|H, S i O.|H, S and O.'),
      Nq('¿Cuántos átomos hay en una molécula de H₂O?|Quants àtoms hi ha en una molècula d’H₂O?|How many atoms are in one molecule of H₂O?', 3, [2, 1, 4], '2 de hidrógeno y 1 de oxígeno.|2 d’hidrogen i 1 d’oxigen.|2 hydrogen and 1 oxygen.'),
      TF('Con electrólisis, el agua se descompone en hidrógeno y oxígeno.|Amb electròlisi, l’aigua es descompon en hidrogen i oxigen.|Electrolysis breaks water down into hydrogen and oxygen.', true, 'Por eso el agua es un compuesto.|Per això l’aigua és un compost.|That is why water is a compound.'),
      TF('Un compuesto tiene las mismas propiedades que los elementos que lo forman.|Un compost té les mateixes propietats que els elements que el formen.|A compound has the same properties as the elements in it.', false, 'El sodio y el cloro son peligrosos; la sal no.|El sodi i el clor són perillosos; la sal no.|Sodium and chlorine are dangerous; salt is not.'),
    ]),
  '2E-FQ-15': lesson(['En los dibujos de partículas, cada círculo es un átomo y cada color, un elemento. Átomos unidos forman moléculas. Sustancia pura: todas las partículas iguales. Mezcla: partículas distintas.|En els dibuixos de partícules, cada cercle és un àtom i cada color, un element. Àtoms units formen molècules. Substància pura: totes les partícules iguals. Mescla: partícules diferents.|In particle diagrams, each circle is an atom and each colour an element. Joined atoms make molecules. Pure substance: all particles the same. Mixture: different particles.'],
    'Un dibujo tiene moléculas 🔴🔴 y moléculas 🔵🔵 mezcladas. ¿Qué es?|Un dibuix té molècules 🔴🔴 i molècules 🔵🔵 mesclades. Què és?|A diagram shows 🔴🔴 molecules mixed with 🔵🔵 molecules. What is it?', ['Hay dos tipos de molécula.|Hi ha dos tipus de molècula.|There are two kinds of molecule.', 'Cada una es un elemento: es una mezcla de dos elementos.|Cada una és un element: és una mescla de dos elements.|Each is an element: it is a mixture of two elements.'], [
      M('Todas las partículas son 🔴🔵 iguales. Es…|Totes les partícules són 🔴🔵 iguals. És…|Every particle is the same 🔴🔵. It is…', 'un compuesto|un compost|a compound', ['un elemento|un element|an element', 'una mezcla|una mescla|a mixture'], 'Una sola sustancia con dos tipos de átomo.|Una sola substància amb dos tipus d’àtom.|One substance with two kinds of atom.'),
      M('Todas las partículas son 🔴🔴. Es…|Totes les partícules són 🔴🔴. És…|Every particle is 🔴🔴. It is…', 'un elemento|un element|an element', ['un compuesto|un compost|a compound', 'una mezcla|una mescla|a mixture'], 'Un solo tipo de átomo.|Un sol tipus d’àtom.|Only one kind of atom.'),
      M('Hay partículas 🔴, 🔵🔵 y 🔴🔵 juntas. Es…|Hi ha partícules 🔴, 🔵🔵 i 🔴🔵 juntes. És…|There are 🔴, 🔵🔵 and 🔴🔵 particles together. It is…', 'una mezcla|una mescla|a mixture', ['un compuesto|un compost|a compound', 'un elemento|un element|an element'], 'Hay sustancias distintas.|Hi ha substàncies diferents.|There are different substances.'),
      TF('En un dibujo de un sólido, las partículas se dibujan juntas y ordenadas.|En un dibuix d’un sòlid, les partícules es dibuixen juntes i ordenades.|In a diagram of a solid, the particles are drawn close and in order.', true, 'En un gas, separadas y desordenadas.|En un gas, separades i desordenades.|In a gas, far apart and random.'),
      Nq('¿Cuántos átomos tiene la molécula 🔴🔵🔵?|Quants àtoms té la molècula 🔴🔵🔵?|How many atoms are in the molecule 🔴🔵🔵?', 3, [2, 1, 6], 'Cuenta los círculos.|Compta els cercles.|Count the circles.'),
      M('La molécula 🔴🔵🔵, con 🔴 = C y 🔵 = O, es…|La molècula 🔴🔵🔵, amb 🔴 = C i 🔵 = O, és…|The molecule 🔴🔵🔵, with 🔴 = C and 🔵 = O, is…', 'CO₂|CO₂|CO₂', ['C₂O|C₂O|C₂O', 'CO|CO|CO'], 'Un carbono y dos oxígenos.|Un carboni i dos oxígens.|One carbon and two oxygens.'),
    ]),
  '2E-FQ-16': G(['Un elemento está formado por átomos con el mismo número de protones (número atómico Z). El número másico A = protones + neutrones. La masa atómica se mide en unidades de masa atómica (u).|Un element està format per àtoms amb el mateix nombre de protons (nombre atòmic Z). El nombre màssic A = protons + neutrons. La massa atòmica es mesura en unitats de massa atòmica (u).|An element is made of atoms with the same number of protons (atomic number Z). Mass number A = protons + neutrons. Atomic mass is measured in atomic mass units (u).'],
    'Carbono: Z = 6, A = 12. ¿Neutrones?|Carboni: Z = 6, A = 12. Neutrons?|Carbon: Z = 6, A = 12. Neutrons?', ['Neutrones = A − Z.|Neutrons = A − Z.|Neutrons = A − Z.', '12 − 6 = 6.|12 − 6 = 6.|12 − 6 = 6.'], atomParts()),
  '2E-FQ-17': lesson(['La tabla periódica ordena los elementos por número atómico. Las filas son periodos y las columnas, grupos; los elementos de un grupo tienen propiedades parecidas. A la izquierda, metales; a la derecha, no metales; en el extremo, gases nobles.|La taula periòdica ordena els elements per nombre atòmic. Les files són períodes i les columnes, grups; els elements d’un grup tenen propietats semblants. A l’esquerra, metalls; a la dreta, no metalls; a l’extrem, gasos nobles.|The periodic table orders the elements by atomic number. Rows are periods and columns are groups; elements in a group behave alike. Metals are on the left, non-metals on the right, noble gases at the far right.'],
    '¿Qué tienen en común el Li, el Na y el K?|Què tenen en comú el Li, el Na i el K?|What do Li, Na and K have in common?', ['Están en el grupo 1 (alcalinos).|Estan en el grup 1 (alcalins).|They are in group 1 (alkali metals).', 'Son metales muy reactivos con el agua.|Són metalls molt reactius amb l’aigua.|They are metals that react strongly with water.'], [
      M('El símbolo Fe corresponde al…|El símbol Fe correspon al…|The symbol Fe stands for…', 'hierro|ferro|iron', ['flúor|fluor|fluorine', 'fósforo|fòsfor|phosphorus'], 'Del latín ferrum.|Del llatí ferrum.|From the Latin ferrum.'),
      M('¿Cuál es un gas noble?|Quin és un gas noble?|Which is a noble gas?', 'el helio (He)|l’heli (He)|helium (He)', ['el hidrógeno (H)|l’hidrogen (H)|hydrogen (H)', 'el oxígeno (O)|l’oxigen (O)|oxygen (O)'], 'Grupo 18: casi no reaccionan.|Grup 18: quasi no reaccionen.|Group 18: they hardly react.'),
      M('Las filas horizontales de la tabla periódica se llaman…|Les files horitzontals de la taula periòdica es diuen…|The rows of the periodic table are called…', 'periodos|períodes|periods', ['grupos|grups|groups', 'familias de gases|famílies de gasos|gas families'], 'Las columnas son grupos.|Les columnes són grups.|The columns are groups.'),
      M('Na es el símbolo del…|Na és el símbol del…|Na is the symbol for…', 'sodio|sodi|sodium', ['nitrógeno|nitrogen|nitrogen', 'níquel|níquel|nickel'], 'Del latín natrium.|Del llatí natrium.|From the Latin natrium.'),
      M('La mayoría de los elementos son…|La majoria dels elements són…|Most elements are…', 'metales|metalls|metals', ['no metales|no metalls|non-metals', 'gases nobles|gasos nobles|noble gases'], 'Ocupan casi toda la izquierda y el centro.|Ocupen quasi tota l’esquerra i el centre.|They fill most of the left and middle.'),
      TF('Los elementos de un mismo grupo tienen propiedades químicas parecidas.|Els elements d’un mateix grup tenen propietats químiques semblants.|Elements in the same group have similar chemical properties.', true, 'Por eso Mendeléiev pudo predecir elementos.|Per això Mendeléiev va poder predir elements.|That is how Mendeleev predicted elements.'),
    ]),
  '2E-FQ-18': lesson(['Casi todo el universo es hidrógeno y helio. Los elementos más pesados se forman en las estrellas (fusión nuclear) y en explosiones de supernovas. En la Tierra y en los seres vivos abundan O, Si, Fe, C, H y N.|Quasi tot l’univers és hidrogen i heli. Els elements més pesants es formen en les estreles (fusió nuclear) i en explosions de supernoves. En la Terra i en els éssers vius abunden O, Si, Fe, C, H i N.|Almost all the universe is hydrogen and helium. Heavier elements are made in stars (nuclear fusion) and supernova explosions. On Earth and in living things, O, Si, Fe, C, H and N are plentiful.'],
    '¿De dónde viene el carbono de nuestro cuerpo?|D’on ve el carboni del nostre cos?|Where does the carbon in our bodies come from?', ['Se formó en el interior de estrellas antiguas.|Es va formar a l’interior d’estreles antigues.|It formed inside ancient stars.', 'Somos «polvo de estrellas».|Som «pols d’estreles».|We are "stardust".'], [
      M('¿Cuál es el elemento más abundante del universo?|Quin és l’element més abundant de l’univers?|What is the most abundant element in the universe?', 'hidrógeno|hidrogen|hydrogen', ['oxígeno|oxigen|oxygen', 'hierro|ferro|iron'], 'Es el más sencillo: 1 protón.|És el més senzill: 1 protó.|It is the simplest: 1 proton.'),
      M('Las estrellas brillan gracias a…|Les estreles brillen gràcies a…|Stars shine because of…', 'la fusión nuclear|la fusió nuclear|nuclear fusion', ['la combustión|la combustió|burning', 'la electricidad|l’electricitat|electricity'], 'Unen núcleos ligeros y liberan energía.|Unixen nuclis lleugers i alliberen energia.|They join light nuclei and release energy.'),
      M('¿Qué elemento es el más abundante en la corteza terrestre?|Quin element és el més abundant en l’escorça terrestre?|Which element is the most abundant in the Earth’s crust?', 'oxígeno|oxigen|oxygen', ['hidrógeno|hidrogen|hydrogen', 'oro|or|gold'], 'Está en casi todas las rocas.|Està en quasi totes les roques.|It is in almost every rock.'),
      M('¿Qué cuatro elementos forman la mayor parte de los seres vivos?|Quins quatre elements formen la major part dels éssers vius?|Which four elements make up most of living things?', 'C, H, O y N|C, H, O i N|C, H, O and N', ['Fe, Cu, Au y Ag|Fe, Cu, Au i Ag|Fe, Cu, Au and Ag', 'He, Ne, Ar y Kr|He, Ne, Ar i Kr|He, Ne, Ar and Kr'], 'Carbono, hidrógeno, oxígeno y nitrógeno.|Carboni, hidrogen, oxigen i nitrogen.|Carbon, hydrogen, oxygen and nitrogen.'),
      TF('Los elementos más pesados que el hierro se forman sobre todo en explosiones de estrellas.|Els elements més pesants que el ferro es formen sobretot en explosions d’estreles.|Elements heavier than iron form mostly in exploding stars.', true, 'En supernovas y choques de estrellas de neutrones.|En supernoves i xocs d’estreles de neutrons.|In supernovae and neutron-star collisions.'),
      M('El segundo elemento más abundante del universo es…|El segon element més abundant de l’univers és…|The second most abundant element in the universe is…', 'helio|heli|helium', ['carbono|carboni|carbon', 'oxígeno|oxigen|oxygen'], 'Se forma al fusionar hidrógeno.|Es forma en fusionar hidrogen.|It forms when hydrogen fuses.'),
    ]),
  '2E-FQ-19': lesson(['En una reacción química, unas sustancias (reactivos) se transforman en otras nuevas (productos). Señales: cambio de color, desprendimiento de gas, formación de un sólido, luz o calor.|En una reacció química, unes substàncies (reactius) es transformen en altres de noves (productes). Senyals: canvi de color, despreniment de gas, formació d’un sòlid, llum o calor.|In a chemical reaction, some substances (reactants) turn into new ones (products). Signs: colour change, gas given off, a solid forming, light or heat.', 'En un cambio físico (fundir, romper, disolver) no aparecen sustancias nuevas.|En un canvi físic (fondre, trencar, dissoldre) no apareixen substàncies noves.|In a physical change (melting, breaking, dissolving) no new substances form.'],
    '¿Quemar papel es un cambio físico o químico?|Cremar paper és un canvi físic o químic?|Is burning paper a physical or chemical change?', ['Aparecen cenizas, humo y gases nuevos.|Apareixen cendres, fum i gasos nous.|Ash, smoke and new gases appear.', 'Es químico.|És químic.|It is chemical.'], [
      M('¿Cuál es un cambio químico?|Quin és un canvi químic?|Which is a chemical change?', 'cocinar un huevo|cuinar un ou|cooking an egg', ['romper un vaso|trencar un got|breaking a glass', 'fundir hielo|fondre gel|melting ice'], 'Las proteínas se transforman.|Les proteïnes es transformen.|The proteins change.'),
      M('¿Cuál es un cambio físico?|Quin és un canvi físic?|Which is a physical change?', 'disolver azúcar en agua|dissoldre sucre en aigua|dissolving sugar in water', ['oxidarse un clavo|oxidar-se un clau|a nail rusting', 'fermentar el mosto|fermentar el most|grape juice fermenting'], 'El azúcar sigue siendo azúcar.|El sucre continua sent sucre.|The sugar is still sugar.'),
      M('En una reacción, las sustancias iniciales se llaman…|En una reacció, les substàncies inicials es diuen…|In a reaction, the starting substances are called…', 'reactivos|reactius|reactants', ['productos|productes|products', 'catalizadores|catalitzadors|catalysts'], 'Los productos son las nuevas.|Els productes són les noves.|The products are the new ones.'),
      TF('Si al mezclar dos líquidos salen burbujas, puede ser una reacción química.|Si en mesclar dos líquids ixen bombolles, pot ser una reacció química.|If bubbles appear when two liquids are mixed, it may be a chemical reaction.', true, 'Se forma un gas nuevo.|Es forma un gas nou.|A new gas is forming.'),
      TF('Al hervir el agua se forma una sustancia nueva.|En bullir l’aigua es forma una substància nova.|Boiling water makes a new substance.', false, 'El vapor sigue siendo agua: es un cambio físico.|El vapor continua sent aigua: és un canvi físic.|Steam is still water: it is a physical change.'),
      M('Vinagre y bicarbonato producen burbujas de…|Vinagre i bicarbonat produïxen bombolles de…|Vinegar and bicarbonate of soda produce bubbles of…', 'dióxido de carbono|diòxid de carboni|carbon dioxide', ['oxígeno|oxigen|oxygen', 'vapor de agua|vapor d’aigua|steam'], 'Es una reacción ácido-base.|És una reacció àcid-base.|It is an acid–base reaction.'),
    ]),
  '2E-FQ-20': lesson(['Tipos de reacciones: síntesis (A + B → AB), descomposición (AB → A + B), sustitución, combustión (con oxígeno, desprende energía) y ácido-base (neutralización).|Tipus de reaccions: síntesi (A + B → AB), descomposició (AB → A + B), substitució, combustió (amb oxigen, desprén energia) i àcid-base (neutralització).|Types of reaction: synthesis (A + B → AB), decomposition (AB → A + B), displacement, combustion (with oxygen, releases energy) and acid–base (neutralisation).'],
    '2 H₂ + O₂ → 2 H₂O. ¿Tipo?|2 H₂ + O₂ → 2 H₂O. Tipus?|2 H₂ + O₂ → 2 H₂O. Which type?', ['Dos sustancias forman una.|Dues substàncies en formen una.|Two substances form one.', 'Síntesis (y también combustión del hidrógeno).|Síntesi (i també combustió de l’hidrogen).|Synthesis (and also combustion of hydrogen).'], [
      M('CaCO₃ → CaO + CO₂ es una reacción de…|CaCO₃ → CaO + CO₂ és una reacció de…|CaCO₃ → CaO + CO₂ is a…', 'descomposición|descomposició|decomposition', ['síntesis|síntesi|synthesis', 'neutralización|neutralització|neutralisation'], 'Una sustancia se rompe en dos.|Una substància es trenca en dues.|One substance splits into two.'),
      M('Ácido + base → sal + agua es una…|Àcid + base → sal + aigua és una…|Acid + base → salt + water is a…', 'neutralización|neutralització|neutralisation', ['combustión|combustió|combustion', 'descomposición|descomposició|decomposition'], 'El ácido y la base se anulan.|L’àcid i la base s’anul·len.|The acid and base cancel out.'),
      M('Fe + S → FeS es una reacción de…|Fe + S → FeS és una reacció de…|Fe + S → FeS is a…', 'síntesis|síntesi|synthesis', ['descomposición|descomposició|decomposition', 'combustión|combustió|combustion'], 'Dos elementos forman un compuesto.|Dos elements formen un compost.|Two elements form a compound.'),
      TF('En una combustión siempre interviene el oxígeno.|En una combustió sempre intervé l’oxigen.|Oxygen always takes part in combustion.', true, 'Es el comburente.|És el comburent.|It is the oxidiser.'),
      M('Zn + CuSO₄ → ZnSO₄ + Cu es una reacción de…|Zn + CuSO₄ → ZnSO₄ + Cu és una reacció de…|Zn + CuSO₄ → ZnSO₄ + Cu is a…', 'sustitución|substitució|displacement', ['síntesis|síntesi|synthesis', 'neutralización|neutralització|neutralisation'], 'El cinc ocupa el lugar del cobre.|El zinc ocupa el lloc del coure.|Zinc takes copper’s place.'),
      M('La electrólisis del agua (2 H₂O → 2 H₂ + O₂) es…|L’electròlisi de l’aigua (2 H₂O → 2 H₂ + O₂) és…|Electrolysis of water (2 H₂O → 2 H₂ + O₂) is…', 'descomposición|descomposició|decomposition', ['síntesis|síntesi|synthesis', 'combustión|combustió|combustion'], 'El agua se separa en sus elementos.|L’aigua se separa en els seus elements.|Water splits into its elements.'),
    ]),
  '2E-FQ-21': G(['Ley de conservación de la masa (Lavoisier): en una reacción química, la masa total de los reactivos es igual a la de los productos. Los átomos no se crean ni se destruyen: se reorganizan.|Llei de conservació de la massa (Lavoisier): en una reacció química, la massa total dels reactius és igual a la dels productes. Els àtoms no es creen ni es destruïxen: es reorganitzen.|Law of conservation of mass (Lavoisier): in a chemical reaction, the total mass of the reactants equals that of the products. Atoms are neither created nor destroyed: they rearrange.'],
    '56 g de hierro + 32 g de azufre. ¿Masa de sulfuro de hierro?|56 g de ferro + 32 g de sofre. Massa de sulfur de ferro?|56 g of iron + 32 g of sulfur. Mass of iron sulfide?', ['La masa se conserva.|La massa es conserva.|Mass is conserved.', '56 + 32 = 88 g.|56 + 32 = 88 g.|56 + 32 = 88 g.'], massConservation()),
  '2E-FQ-22': lesson(['La velocidad de reacción aumenta si: sube la temperatura, aumenta la concentración, los sólidos están más troceados (más superficie) o se usa un catalizador.|La velocitat de reacció augmenta si: puja la temperatura, augmenta la concentració, els sòlids estan més trossejats (més superfície) o s’usa un catalitzador.|Reactions go faster if: temperature rises, concentration increases, solids are cut smaller (more surface) or a catalyst is used.'],
    '¿Por qué los alimentos duran más en la nevera?|Per què els aliments duren més en la nevera?|Why does food last longer in the fridge?', ['Las reacciones que los estropean dependen de la temperatura.|Les reaccions que els fan malbé depenen de la temperatura.|The reactions that spoil it depend on temperature.', 'Con frío van más despacio.|Amb fred van més a poc a poc.|They are slower in the cold.'], [
      M('Una pastilla efervescente se disuelve antes si…|Una pastilla efervescent es dissol abans si…|A fizzy tablet dissolves faster if…', 'está triturada|està triturada|it is crushed', ['está entera|està sencera|it is whole', 'el agua está fría|l’aigua està freda|the water is cold'], 'Más superficie de contacto.|Més superfície de contacte.|More surface area.'),
      M('Un catalizador…|Un catalitzador…|A catalyst…', 'acelera la reacción sin gastarse|accelera la reacció sense gastar-se|speeds up a reaction without being used up', ['se convierte en producto|es convertix en producte|becomes a product', 'detiene la reacción|atura la reacció|stops the reaction'], 'Las enzimas son catalizadores biológicos.|Els enzims són catalitzadors biològics.|Enzymes are biological catalysts.'),
      TF('Al aumentar la temperatura, las reacciones suelen ir más rápido.|En augmentar la temperatura, les reaccions solen anar més ràpid.|Raising the temperature usually speeds up reactions.', true, 'Las partículas chocan más y con más energía.|Les partícules xoquen més i amb més energia.|Particles collide more often and harder.'),
      M('El vinagre más concentrado reacciona con el bicarbonato…|El vinagre més concentrat reacciona amb el bicarbonat…|More concentrated vinegar reacts with bicarbonate…', 'más deprisa|més de pressa|faster', ['más despacio|més a poc a poc|more slowly', 'igual|igual|the same'], 'Más partículas que pueden chocar.|Més partícules que poden xocar.|More particles to collide.'),
      M('La serrín arde más rápido que un tronco porque…|La serradura crema més ràpid que un tronc perquè…|Sawdust burns faster than a log because…', 'tiene más superficie en contacto con el oxígeno|té més superfície en contacte amb l’oxigen|it has more surface in contact with oxygen', ['es más pesado|és més pesant|it is heavier', 'tiene más agua|té més aigua|it has more water'], 'Trozos pequeños, más superficie.|Trossos xicotets, més superfície.|Small pieces, more surface.'),
      TF('El catalizador de un coche ayuda a transformar gases contaminantes.|El catalitzador d’un cotxe ajuda a transformar gasos contaminants.|A car’s catalytic converter helps change polluting gases.', true, 'Acelera reacciones que los hacen menos dañinos.|Accelera reaccions que els fan menys nocius.|It speeds up reactions that make them less harmful.'),
    ]),
  '2E-FQ-23': lesson(['La combustión es una reacción de un combustible con oxígeno (comburente) que desprende energía (luz y calor). Necesita combustible, comburente y energía de activación: el triángulo del fuego. Si es completa, produce CO₂ y agua.|La combustió és una reacció d’un combustible amb oxigen (comburent) que desprén energia (llum i calor). Necessita combustible, comburent i energia d’activació: el triangle del foc. Si és completa, produïx CO₂ i aigua.|Combustion is a reaction of a fuel with oxygen (the oxidiser) that releases energy (light and heat). It needs fuel, oxygen and activation energy: the fire triangle. Complete combustion produces CO₂ and water.'],
    '¿Por qué una manta apaga un fuego pequeño?|Per què una manta apaga un foc xicotet?|Why does a blanket put out a small fire?', ['Rompe el triángulo del fuego.|Trenca el triangle del foc.|It breaks the fire triangle.', 'Le quita el oxígeno.|Li lleva l’oxigen.|It removes the oxygen.'], [
      M('En una combustión, el comburente es…|En una combustió, el comburent és…|In combustion, the oxidiser is…', 'el oxígeno|l’oxigen|oxygen', ['la madera|la fusta|the wood', 'la cerilla|el llumí|the match'], 'Sin oxígeno no hay fuego.|Sense oxigen no hi ha foc.|No oxygen, no fire.'),
      M('Productos de la combustión completa del metano:|Productes de la combustió completa del metà:|Products of complete combustion of methane:', 'CO₂ y H₂O|CO₂ i H₂O|CO₂ and H₂O', ['CO y C|CO i C|CO and C', 'O₂ y H₂|O₂ i H₂|O₂ and H₂'], 'Dióxido de carbono y agua.|Diòxid de carboni i aigua.|Carbon dioxide and water.'),
      M('Una combustión incompleta (con poco oxígeno) puede producir…|Una combustió incompleta (amb poc oxigen) pot produir…|Incomplete combustion (little oxygen) can produce…', 'monóxido de carbono, muy tóxico|monòxid de carboni, molt tòxic|carbon monoxide, which is very toxic', ['oxígeno puro|oxigen pur|pure oxygen', 'agua destilada|aigua destil·lada|distilled water'], 'Por eso hay que ventilar estufas y calentadores.|Per això cal ventilar estufes i escalfadors.|That is why heaters must be ventilated.'),
      TF('Echar agua a un fuego de aceite es peligroso.|Tirar aigua a un foc d’oli és perillós.|Throwing water on an oil fire is dangerous.', true, 'El agua salta y extiende el aceite ardiendo.|L’aigua esclata i escampa l’oli encés.|The water spits and spreads the burning oil.'),
      M('La cerilla aporta al fuego…|El llumí aporta al foc…|The match gives the fire…', 'la energía de activación|l’energia d’activació|the activation energy', ['el combustible principal|el combustible principal|the main fuel', 'el comburente|el comburent|the oxidiser'], 'Inicia la reacción.|Inicia la reacció.|It starts the reaction.'),
      TF('Quemar combustibles fósiles emite CO₂, que contribuye al cambio climático.|Cremar combustibles fòssils emet CO₂, que contribuïx al canvi climàtic.|Burning fossil fuels releases CO₂, which adds to climate change.', true, 'Es un gas de efecto invernadero.|És un gas d’efecte d’hivernacle.|It is a greenhouse gas.'),
    ]),
  '2E-FQ-24': lesson(['La oxidación es una reacción en la que una sustancia se combina con oxígeno (o pierde electrones). El hierro se oxida con oxígeno y humedad y forma herrumbre. Se evita pintando, engrasando o galvanizando.|L’oxidació és una reacció en què una substància es combina amb oxigen (o perd electrons). El ferro s’oxida amb oxigen i humitat i forma rovell. S’evita pintant, greixant o galvanitzant.|Oxidation is a reaction in which a substance combines with oxygen (or loses electrons). Iron rusts with oxygen and moisture. Painting, greasing or galvanising prevents it.'],
    '¿Por qué una manzana cortada se pone marrón?|Per què una poma tallada es posa marró?|Why does a cut apple turn brown?', ['Al contacto con el aire, se oxida.|En contacte amb l’aire, s’oxida.|In contact with air, it oxidises.', 'Unas gotas de limón la retrasan.|Unes gotes de llima ho retarden.|A few drops of lemon juice slow it down.'], [
      M('El hierro se oxida antes…|El ferro s’oxida abans…|Iron rusts faster…', 'cerca del mar|prop de la mar|near the sea', ['en un desierto seco|en un desert sec|in a dry desert', 'dentro de aceite|dins d’oli|under oil'], 'La humedad y la sal aceleran la oxidación.|La humitat i la sal acceleren l’oxidació.|Moisture and salt speed up rusting.'),
      M('Para proteger una verja de hierro se puede…|Per a protegir una reixa de ferro es pot…|To protect an iron gate you can…', 'pintarla|pintar-la|paint it', ['mojarla|banyar-la|wet it', 'calentarla|escalfar-la|heat it'], 'La pintura impide que llegue el oxígeno.|La pintura impedix que arribe l’oxigen.|Paint keeps the oxygen out.'),
      TF('La oxidación del hierro es un cambio químico.|L’oxidació del ferro és un canvi químic.|Iron rusting is a chemical change.', true, 'Se forma óxido de hierro, una sustancia nueva.|Es forma òxid de ferro, una substància nova.|Iron oxide, a new substance, forms.'),
      M('Galvanizar el hierro es…|Galvanitzar el ferro és…|Galvanising iron means…', 'recubrirlo de cinc|recobrir-lo de zinc|coating it with zinc', ['pintarlo de rojo|pintar-lo de roig|painting it red', 'fundirlo|fondre’l|melting it'], 'El cinc lo protege.|El zinc el protegix.|The zinc protects it.'),
      TF('La combustión es un tipo de oxidación rápida.|La combustió és un tipus d’oxidació ràpida.|Combustion is a fast kind of oxidation.', true, 'Ambas usan oxígeno; la combustión desprende luz y calor.|Totes dues usen oxigen; la combustió desprén llum i calor.|Both use oxygen; combustion gives off light and heat.'),
      M('El oro casi no se oxida. Por eso…|L’or quasi no s’oxida. Per això…|Gold hardly oxidises. That is why…', 'las joyas antiguas siguen brillando|les joies antigues continuen brillant|ancient jewellery still shines', ['es muy barato|és molt barat|it is very cheap', 'es magnético|és magnètic|it is magnetic'], 'Es un metal poco reactivo.|És un metall poc reactiu.|It is an unreactive metal.'),
    ]),
  '2E-FQ-25': lesson(['Los ácidos tienen sabor agrio (vinagre, limón); las bases o álcalis, amargo y tacto jabonoso (lejía, jabón). El pH mide la acidez: menos de 7, ácido; 7, neutro; más de 7, básico. Los indicadores cambian de color según el pH.|Els àcids tenen sabor agre (vinagre, llima); les bases o àlcalis, amarg i tacte sabonós (lleixiu, sabó). El pH mesura l’acidesa: menys de 7, àcid; 7, neutre; més de 7, bàsic. Els indicadors canvien de color segons el pH.|Acids taste sour (vinegar, lemon); bases or alkalis taste bitter and feel soapy (bleach, soap). pH measures acidity: below 7 acidic, 7 neutral, above 7 alkaline. Indicators change colour with pH.', 'Nunca se prueba ni se toca un producto del laboratorio.|Mai es prova ni es toca un producte del laboratori.|Never taste or touch laboratory chemicals.'],
    'El zumo de limón tiene pH 2. ¿Es ácido o básico?|El suc de llima té pH 2. És àcid o bàsic?|Lemon juice has pH 2. Acidic or alkaline?', ['Menor que 7.|Menor que 7.|Below 7.', 'Ácido.|Àcid.|Acidic.'], [
      M('pH = 7 indica una sustancia…|pH = 7 indica una substància…|pH 7 means a substance is…', 'neutra|neutra|neutral', ['ácida|àcida|acidic', 'básica|bàsica|alkaline'], 'Como el agua pura.|Com l’aigua pura.|Like pure water.'),
      M('La lejía tiene pH 12. Es…|El lleixiu té pH 12. És…|Bleach has pH 12. It is…', 'básica|bàsica|alkaline', ['ácida|àcida|acidic', 'neutra|neutra|neutral'], 'Mayor que 7.|Major que 7.|Above 7.'),
      M('Para aliviar la acidez de estómago se toma…|Per a alleujar l’acidesa d’estómac es pren…|To relieve heartburn you take…', 'un antiácido (una base suave)|un antiàcid (una base suau)|an antacid (a mild base)', ['vinagre|vinagre|vinegar', 'zumo de limón|suc de llima|lemon juice'], 'La base neutraliza el exceso de ácido.|La base neutralitza l’excés d’àcid.|The base neutralises the extra acid.'),
      TF('La lluvia ácida puede dañar bosques y monumentos.|La pluja àcida pot danyar boscos i monuments.|Acid rain can damage forests and monuments.', true, 'Se forma con gases de la combustión.|Es forma amb gasos de la combustió.|It forms from combustion gases.'),
      M('¿Qué es más ácido?|Què és més àcid?|Which is more acidic?', 'pH 3|pH 3|pH 3', ['pH 6|pH 6|pH 6', 'pH 9|pH 9|pH 9'], 'Cuanto menor el pH, más ácido.|Com menor és el pH, més àcid.|The lower the pH, the more acidic.'),
      M('El papel indicador universal sirve para…|El paper indicador universal servix per a…|Universal indicator paper is used to…', 'estimar el pH|estimar el pH|estimate pH', ['medir la masa|mesurar la massa|measure mass', 'calentar|escalfar|heat things'], 'Cambia de color según el pH.|Canvia de color segons el pH.|It changes colour with pH.'),
    ]),
  '2E-FQ-26': lesson(['Algunas sustancias químicas son clave en la vida diaria y la industria: el amoníaco (abonos), el ácido sulfúrico (industria), el cloruro de sodio (alimentación), los plásticos (envases), los medicamentos como el ácido acetilsalicílico.|Algunes substàncies químiques són clau en la vida diària i la indústria: l’amoníac (adobs), l’àcid sulfúric (indústria), el clorur de sodi (alimentació), els plàstics (envasos), els medicaments com l’àcid acetilsalicílic.|Some chemicals are key in daily life and industry: ammonia (fertilisers), sulfuric acid (industry), sodium chloride (food), plastics (packaging), medicines such as aspirin.', 'Hay que usarlas con seguridad y reducir su impacto ambiental.|Cal usar-les amb seguretat i reduir el seu impacte ambiental.|They must be used safely and their environmental impact reduced.'],
    '¿Para qué se usa sobre todo el amoníaco?|Per a què s’usa sobretot l’amoníac?|What is ammonia mainly used for?', ['Aporta nitrógeno a las plantas.|Aporta nitrogen a les plantes.|It provides nitrogen for plants.', 'Para fabricar abonos.|Per a fabricar adobs.|To make fertilisers.'], [
      M('¿Qué sustancia es la sal de mesa?|Quina substància és la sal de taula?|What substance is table salt?', 'cloruro de sodio (NaCl)|clorur de sodi (NaCl)|sodium chloride (NaCl)', ['carbonato de calcio|carbonat de calci|calcium carbonate', 'ácido sulfúrico|àcid sulfúric|sulfuric acid'], 'Sodio + cloro.|Sodi + clor.|Sodium + chlorine.'),
      M('El pictograma de una calavera significa…|El pictograma d’una calavera significa…|A skull-and-crossbones pictogram means…', 'tóxico|tòxic|toxic', ['inflamable|inflamable|flammable', 'reciclable|reciclable|recyclable'], 'Puede ser mortal.|Pot ser mortal.|It can be deadly.'),
      M('¿Qué se obtiene del petróleo?|Què s’obté del petroli?|What is obtained from crude oil?', 'plásticos y combustibles|plàstics i combustibles|plastics and fuels', ['sal y azúcar|sal i sucre|salt and sugar', 'oro y plata|or i plata|gold and silver'], 'Se separa en una refinería.|Se separa en una refineria.|It is separated in a refinery.'),
      TF('Nunca se deben mezclar lejía y amoníaco: desprenden gases tóxicos.|Mai s’han de mesclar lleixiu i amoníac: desprenen gasos tòxics.|Never mix bleach and ammonia: they give off toxic gases.', true, 'Lee siempre las etiquetas.|Llig sempre les etiquetes.|Always read the labels.'),
      M('El pictograma de una llama indica…|El pictograma d’una flama indica…|A flame pictogram means…', 'inflamable|inflamable|flammable', ['corrosivo|corrosiu|corrosive', 'tóxico|tòxic|toxic'], 'Lejos del fuego.|Lluny del foc.|Keep away from fire.'),
      M('El carbonato de calcio (CaCO₃) está en…|El carbonat de calci (CaCO₃) està en…|Calcium carbonate (CaCO₃) is found in…', 'la caliza y las conchas|la calcària i les petxines|limestone and shells', ['el aire|l’aire|the air', 'el petróleo|el petroli|crude oil'], 'También en la tiza.|També en el guix.|Also in chalk.'),
    ]),
  '2E-FQ-27': G(['Para describir un movimiento hace falta un sistema de referencia: un punto respecto al que medimos la posición. Rapidez media = distancia recorrida / tiempo empleado.|Per a descriure un moviment cal un sistema de referència: un punt respecte al qual mesurem la posició. Rapidesa mitjana = distància recorreguda / temps emprat.|To describe motion you need a frame of reference: a point from which positions are measured. Average speed = distance travelled ÷ time taken.'],
    'Recorro 1 500 m en 5 min. ¿Rapidez media en m/s?|Recorre 1 500 m en 5 min. Rapidesa mitjana en m/s?|I cover 1,500 m in 5 min. Average speed in m/s?', ['5 min = 300 s.|5 min = 300 s.|5 min = 300 s.', '1 500 / 300 = 5 m/s.|1 500 / 300 = 5 m/s.|1,500 ÷ 300 = 5 m/s.'], speed(), [
      TF('Una persona sentada en un tren en marcha está en reposo respecto al tren.|Una persona asseguda en un tren en marxa està en repòs respecte al tren.|A person sitting on a moving train is at rest relative to the train.', true, 'El movimiento depende del sistema de referencia.|El moviment depén del sistema de referència.|Motion depends on the frame of reference.'),
    ]),
  '2E-FQ-28': G(['En una gráfica posición-tiempo: una recta inclinada es movimiento uniforme (la pendiente es la velocidad); una recta horizontal significa reposo; cuanto más inclinada, más rápido.|En una gràfica posició-temps: una recta inclinada és moviment uniforme (el pendent és la velocitat); una recta horitzontal significa repòs; com més inclinada, més ràpid.|On a position–time graph: a sloping straight line is uniform motion (the gradient is the speed); a flat line means at rest; steeper means faster.'],
    'La posición pasa de 0 m a 20 m en 4 s en línea recta. ¿Velocidad?|La posició passa de 0 m a 20 m en 4 s en línia recta. Velocitat?|Position goes from 0 m to 20 m in 4 s along a straight line. Velocity?', ['Pendiente: 20 / 4.|Pendent: 20 / 4.|Gradient: 20 ÷ 4.', '5 m/s.|5 m/s.|5 m/s.'], motionGraph()),
  '2E-FQ-29': lesson(['La rapidez solo dice cuánto de deprisa; la velocidad también indica dirección y sentido (es un vector). Desplazamiento: distancia en línea recta entre el inicio y el final.|La rapidesa només diu com de ràpid; la velocitat també indica direcció i sentit (és un vector). Desplaçament: distància en línia recta entre l’inici i el final.|Speed only tells how fast; velocity also gives direction (it is a vector). Displacement: straight-line distance from start to finish.'],
    'Doy una vuelta completa a una pista de 400 m. ¿Desplazamiento?|Faig una volta completa a una pista de 400 m. Desplaçament?|I run one full lap of a 400 m track. Displacement?', ['He recorrido 400 m de distancia.|He recorregut 400 m de distància.|I have covered 400 m of distance.', 'Acabo donde empecé: desplazamiento 0.|Acabe on vaig començar: desplaçament 0.|I end where I started: displacement 0.'], [
      M('¿Qué magnitud incluye dirección y sentido?|Quina magnitud inclou direcció i sentit?|Which quantity includes direction?', 'la velocidad|la velocitat|velocity', ['la rapidez|la rapidesa|speed', 'el tiempo|el temps|time'], 'Es una magnitud vectorial.|És una magnitud vectorial.|It is a vector quantity.'),
      Nq('Ando 30 m al este y vuelvo 10 m al oeste. ¿Desplazamiento (m)?|Camine 30 m cap a l’est i torne 10 m cap a l’oest. Desplaçament (m)?|I walk 30 m east and 10 m back west. Displacement (m)?', 20, [40, 10, 30], 'Resta: 30 − 10.|Resta: 30 − 10.|Subtract: 30 − 10.'),
      Nq('En el mismo paseo, ¿distancia recorrida (m)?|En el mateix passeig, distància recorreguda (m)?|On the same walk, distance travelled (m)?', 40, [20, 10, 30], 'Suma todo lo andado: 30 + 10.|Suma tot el que has caminat: 30 + 10.|Add everything walked: 30 + 10.'),
      TF('Dos coches a 50 km/h en sentidos opuestos tienen la misma velocidad.|Dos cotxes a 50 km/h en sentits oposats tenen la mateixa velocitat.|Two cars at 50 km/h in opposite directions have the same velocity.', false, 'Misma rapidez, velocidad distinta (sentido opuesto).|Mateixa rapidesa, velocitat diferent (sentit oposat).|Same speed, different velocity (opposite direction).'),
      TF('Un coche que toma una curva a 60 km/h constantes cambia de velocidad.|Un cotxe que pren una corba a 60 km/h constants canvia de velocitat.|A car going round a bend at a steady 60 km/h is changing velocity.', true, 'Cambia la dirección.|Canvia la direcció.|Its direction changes.'),
      M('El velocímetro de un coche marca…|El velocímetre d’un cotxe marca…|A car’s speedometer shows…', 'la rapidez instantánea|la rapidesa instantània|instantaneous speed', ['la velocidad media del viaje|la velocitat mitjana del viatge|the average velocity of the trip', 'el desplazamiento|el desplaçament|the displacement'], 'Lo que va en cada instante.|El que va en cada instant.|How fast at each moment.'),
    ]),
  '2E-FQ-30': G(['La aceleración mide cómo cambia la velocidad con el tiempo: a = (v − v₀) / t. Se mide en m/s². Si frena, la aceleración es negativa.|L’acceleració mesura com canvia la velocitat amb el temps: a = (v − v₀) / t. Es mesura en m/s². Si frena, l’acceleració és negativa.|Acceleration measures how velocity changes over time: a = (v − u) ÷ t. It is measured in m/s². When slowing down, it is negative.'],
    'Un coche pasa de 0 a 20 m/s en 5 s. ¿Aceleración?|Un cotxe passa de 0 a 20 m/s en 5 s. Acceleració?|A car goes from 0 to 20 m/s in 5 s. Acceleration?', ['(20 − 0) / 5.|(20 − 0) / 5.|(20 − 0) ÷ 5.', '4 m/s².|4 m/s².|4 m/s².'], acceleration()),
  '2E-FQ-31': G(['En caída libre (sin rozamiento), todos los cuerpos caen con la misma aceleración: g ≈ 9,8 m/s² (usamos 10). v = g · t; altura caída h = ½ · g · t².|En caiguda lliure (sense fregament), tots els cossos cauen amb la mateixa acceleració: g ≈ 9,8 m/s² (usem 10). v = g · t; altura caiguda h = ½ · g · t².|In free fall (no air resistance), everything falls with the same acceleration: g ≈ 9.8 m/s² (we use 10). v = g × t; distance fallen h = ½ × g × t².'],
    'Una piedra cae 3 s. ¿Velocidad final?|Una pedra cau 3 s. Velocitat final?|A stone falls for 3 s. Final speed?', ['v = 10 · 3.|v = 10 · 3.|v = 10 × 3.', '30 m/s.|30 m/s.|30 m/s.'], freeFall(), [
      TF('En el vacío, una pluma y un martillo caen a la vez.|En el buit, una ploma i un martell cauen alhora.|In a vacuum, a feather and a hammer fall together.', true, 'Sin aire, no hay rozamiento.|Sense aire, no hi ha fregament.|With no air, there is no air resistance.'),
    ]),
  '2E-FQ-32': lesson(['Una fuerza puede deformar un cuerpo o cambiar su movimiento. Se mide en newtons (N) con un dinamómetro. Es un vector: tiene módulo, dirección y sentido. Fuerzas habituales: peso, rozamiento, normal, tensión.|Una força pot deformar un cos o canviar el seu moviment. Es mesura en newtons (N) amb un dinamòmetre. És un vector: té mòdul, direcció i sentit. Forces habituals: pes, fregament, normal, tensió.|A force can change an object’s shape or motion. It is measured in newtons (N) with a newton meter. It is a vector: it has size and direction. Common forces: weight, friction, normal reaction, tension.', 'Dos fuerzas en la misma dirección se suman si van en el mismo sentido y se restan si van en sentidos opuestos.|Dues forces en la mateixa direcció se sumen si van en el mateix sentit i es resten si van en sentits oposats.|Two forces along the same line add if they point the same way and subtract if they point opposite ways.'],
    'Empujo una caja con 30 N hacia la derecha y mi amiga con 20 N hacia la izquierda. ¿Fuerza resultante?|Empente una caixa amb 30 N cap a la dreta i la meua amiga amb 20 N cap a l’esquerra. Força resultant?|I push a box 30 N to the right and my friend pushes 20 N to the left. Resultant force?', ['Sentidos opuestos: se restan.|Sentits oposats: es resten.|Opposite directions: subtract.', '10 N hacia la derecha.|10 N cap a la dreta.|10 N to the right.'], [
      Nq('Dos personas tiran de una cuerda en el mismo sentido con 40 N y 25 N. ¿Resultante (N)?|Dues persones estiren d’una corda en el mateix sentit amb 40 N i 25 N. Resultant (N)?|Two people pull a rope the same way with 40 N and 25 N. Resultant (N)?', 65, [15, 40, 1000], 'Mismo sentido: se suman.|Mateix sentit: se sumen.|Same direction: add.'),
      M('¿Con qué instrumento se miden las fuerzas?|Amb quin instrument es mesuren les forces?|What instrument measures forces?', 'el dinamómetro|el dinamòmetre|a newton meter', ['la balanza|la balança|a balance', 'el termómetro|el termòmetre|a thermometer'], 'Tiene un muelle que se estira.|Té un moll que s’estira.|It has a spring that stretches.'),
      M('¿Qué fuerza frena un libro que desliza sobre la mesa?|Quina força frena un llibre que llisca sobre la taula?|Which force slows a book sliding on a table?', 'el rozamiento|el fregament|friction', ['el peso|el pes|weight', 'la normal|la normal|the normal force'], 'Se opone al movimiento.|S’oposa al moviment.|It opposes motion.'),
      TF('Si la resultante de las fuerzas es cero, un cuerpo en reposo sigue en reposo.|Si la resultant de les forces és zero, un cos en repòs continua en repòs.|If the resultant force is zero, an object at rest stays at rest.', true, 'Las fuerzas están equilibradas.|Les forces estan equilibrades.|The forces are balanced.'),
      M('La unidad de fuerza en el SI es…|La unitat de força en el SI és…|The SI unit of force is…', 'el newton (N)|el newton (N)|the newton (N)', ['el kilogramo (kg)|el quilogram (kg)|the kilogram (kg)', 'el julio (J)|el joule (J)|the joule (J)'], 'En honor a Isaac Newton.|En honor d’Isaac Newton.|Named after Isaac Newton.'),
      TF('Una plastilina aplastada es un efecto de una fuerza.|Una plastilina aixafada és un efecte d’una força.|Squashed modelling clay is an effect of a force.', true, 'Las fuerzas deforman.|Les forces deformen.|Forces change shape.'),
    ]),
  '2E-FQ-33': G(['Segunda ley de Newton: F = m · a. Una misma fuerza acelera menos a un cuerpo de más masa. El peso es la fuerza con que la Tierra atrae: P = m · g.|Segona llei de Newton: F = m · a. Una mateixa força accelera menys un cos de més massa. El pes és la força amb què la Terra atrau: P = m · g.|Newton’s second law: F = m × a. The same force accelerates a heavier object less. Weight is the Earth’s pull: W = m × g.'],
    'F = 100 N sobre 20 kg. ¿Aceleración?|F = 100 N sobre 20 kg. Acceleració?|F = 100 N on 20 kg. Acceleration?', ['a = F / m = 100 / 20.|a = F / m = 100 / 20.|a = F ÷ m = 100 ÷ 20.', '5 m/s².|5 m/s².|5 m/s².'], newton()),
  '2E-FQ-34': lesson(['Fuerzas a distancia: la eléctrica (entre cargas: iguales se repelen, distintas se atraen) y la magnética (entre imanes: polos iguales se repelen, distintos se atraen). La Tierra se comporta como un gran imán: por eso funciona la brújula.|Forces a distància: l’elèctrica (entre càrregues: iguals es repel·lixen, diferents s’atrauen) i la magnètica (entre imants: pols iguals es repel·lixen, diferents s’atrauen). La Terra es comporta com un gran imant: per això funciona la brúixola.|Non-contact forces: electric (between charges: like charges repel, unlike attract) and magnetic (between magnets: like poles repel, unlike attract). The Earth behaves like a big magnet, which is why a compass works.'],
    'Froto un globo con el pelo y se pega a la pared. ¿Por qué?|Fregue un globus amb els cabells i s’apega a la paret. Per què?|I rub a balloon on my hair and it sticks to the wall. Why?', ['El globo se carga al ganar electrones.|El globus es carrega en guanyar electrons.|The balloon becomes charged by gaining electrons.', 'Atrae las cargas de la pared: fuerza eléctrica.|Atrau les càrregues de la paret: força elèctrica.|It attracts charges in the wall: electric force.'], [
      M('Dos polos norte de dos imanes…|Dos pols nord de dos imants…|Two north poles of magnets…', 'se repelen|es repel·lixen|repel', ['se atraen|s’atrauen|attract', 'no se afectan|no s’afecten|do not affect each other'], 'Polos iguales se repelen.|Pols iguals es repel·lixen.|Like poles repel.'),
      M('Una carga positiva y una negativa…|Una càrrega positiva i una negativa…|A positive and a negative charge…', 'se atraen|s’atrauen|attract', ['se repelen|es repel·lixen|repel', 'se anulan siempre|s’anul·len sempre|always cancel'], 'Cargas distintas se atraen.|Càrregues diferents s’atrauen.|Unlike charges attract.'),
      M('¿Qué material atrae un imán?|Quin material atrau un imant?|Which material does a magnet attract?', 'hierro|ferro|iron', ['plástico|plàstic|plastic', 'aluminio|alumini|aluminium'], 'Hierro, níquel y cobalto son magnéticos.|Ferro, níquel i cobalt són magnètics.|Iron, nickel and cobalt are magnetic.'),
      TF('La aguja de una brújula apunta al norte por el magnetismo terrestre.|L’agulla d’una brúixola apunta al nord pel magnetisme terrestre.|A compass needle points north because of the Earth’s magnetism.', true, 'La Tierra es como un gran imán.|La Terra és com un gran imant.|The Earth is like a giant magnet.'),
      TF('La fuerza magnética necesita contacto.|La força magnètica necessita contacte.|Magnetic force needs contact.', false, 'Actúa a distancia.|Actua a distància.|It acts at a distance.'),
      M('Un electroimán es…|Un electroimant és…|An electromagnet is…', 'un imán que funciona con corriente eléctrica|un imant que funciona amb corrent elèctric|a magnet that works with electric current', ['un imán de nevera|un imant de nevera|a fridge magnet', 'una pila|una pila|a battery'], 'Se apaga al cortar la corriente.|S’apaga en tallar el corrent.|It switches off when the current stops.'),
    ]),
};
export default P;
